const latido = (s: number, t0: number) => {
if (s < t0) return 0;
const f = (s - t0) % 0.85;
const a = Math.exp(-f * 16);
const b = f > 0.2 ? 0.65 * Math.exp(-(f - 0.2) * 16) : 0;
return Math.min(1, a + b);
};
